    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Deep navy/slate with amber accent — analytical, data-forward
           =========================================== */
        :root {
            --bg-primary: #0c1220;
            --bg-secondary: #111d30;
            --bg-card: #162035;
            --bg-table-head: #1a2845;
            --bg-table-alt: #0f1a2e;
            --text-primary: #e8edf5;
            --text-secondary: #8899b4;
            --text-muted: #526278;
            --accent: #f5a623;
            --accent-dim: rgba(245, 166, 35, 0.18);
            --accent-glow: rgba(245, 166, 35, 0.4);
            --accent2: #4a9eff;
            --accent2-dim: rgba(74, 158, 255, 0.15);
            --accent3: #00d4aa;
            --accent3-dim: rgba(0, 212, 170, 0.15);
            --danger: #ff5f6b;
            --border: rgba(255, 255, 255, 0.06);
            --border-bright: rgba(245, 166, 35, 0.35);

            /* Typography */
            --font-display: 'DM Serif Display', Georgia, serif;
            --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
            --font-body: 'DM Sans', system-ui, sans-serif;

            /* Sizes — all use clamp() */
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.75rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --mono-size: clamp(0.65rem, 1.1vw, 0.9rem);

            /* Spacing */
            --slide-padding: clamp(1rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 2rem);
            --element-gap: clamp(0.25rem, 1vw, 1rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           RESET
           =========================================== */
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT BASE CSS (mandatory)
           =========================================== */
        html, body { height: 100%; overflow-x: hidden; }
        html { scroll-snap-type: y mandatory; scroll-behavior: smooth; }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list { gap: clamp(0.4rem, 1vh, 1rem); }
        .feature-list li, .bullet-list li { font-size: var(--body-size); line-height: 1.4; }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* Short viewports */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.2s !important; }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL BASE STYLES
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
        }

        /* ===========================================
           BACKGROUND EFFECTS
           =========================================== */
        .slide-bg {
            position: absolute;
            inset: 0;
            z-index: 0;
            pointer-events: none;
        }

        /* Grid overlay for techy feel */
        .grid-overlay {
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(74, 158, 255, 0.025) 1px, transparent 1px),
                linear-gradient(90deg, rgba(74, 158, 255, 0.025) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
        }

        /* Corner accent marks */
        .corner-tl, .corner-br {
            position: absolute;
            width: clamp(30px, 4vw, 60px);
            height: clamp(30px, 4vw, 60px);
            opacity: 0.4;
            pointer-events: none;
        }
        .corner-tl {
            top: clamp(12px, 2vw, 24px);
            left: clamp(12px, 2vw, 24px);
            border-top: 2px solid var(--accent);
            border-left: 2px solid var(--accent);
        }
        .corner-br {
            bottom: clamp(12px, 2vw, 24px);
            right: clamp(12px, 2vw, 24px);
            border-bottom: 2px solid var(--accent);
            border-right: 2px solid var(--accent);
        }

        /* Slide counter badge */
        .slide-num {
            position: absolute;
            bottom: clamp(10px, 1.5vw, 20px);
            left: var(--slide-padding);
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            letter-spacing: 0.1em;
            z-index: 10;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .reveal-left {
            opacity: 0;
            transform: translateX(calc(-1 * clamp(20px, 3vw, 40px)));
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .reveal-scale {
            opacity: 0;
            transform: scale(0.93);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal,
        .slide.visible .reveal-left,
        .slide.visible .reveal-scale {
            opacity: 1;
            transform: none;
        }

        /* Staggered delays for children */
        .stagger > *:nth-child(1) { transition-delay: 0.05s; }
        .stagger > *:nth-child(2) { transition-delay: 0.15s; }
        .stagger > *:nth-child(3) { transition-delay: 0.25s; }
        .stagger > *:nth-child(4) { transition-delay: 0.35s; }
        .stagger > *:nth-child(5) { transition-delay: 0.45s; }
        .stagger > *:nth-child(6) { transition-delay: 0.55s; }

        /* ===========================================
           SLIDE 1 — TITLE SLIDE
           =========================================== */
        #slide-1 {
            background:
                radial-gradient(ellipse at 10% 90%, rgba(245, 166, 35, 0.12) 0%, transparent 55%),
                radial-gradient(ellipse at 90% 10%, rgba(74, 158, 255, 0.1) 0%, transparent 55%),
                var(--bg-primary);
        }

        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--accent);
            margin-bottom: clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .title-main {
            font-family: var(--font-display);
            font-size: clamp(1.6rem, 4.5vw, 3.8rem);
            line-height: 1.1;
            color: var(--text-primary);
            max-width: 14em;
            margin-bottom: clamp(0.75rem, 2vw, 2rem);
        }

        .title-main em {
            font-style: italic;
            color: var(--accent);
        }

        .title-headline {
            display: inline-flex;
            align-items: center;
            gap: clamp(0.4rem, 1vw, 1rem);
            background: var(--accent-dim);
            border: 1px solid var(--border-bright);
            border-radius: 6px;
            padding: clamp(0.3rem, 0.8vw, 0.7rem) clamp(0.6rem, 1.5vw, 1.4rem);
            font-family: var(--font-mono);
            font-size: clamp(0.65rem, 1.4vw, 1.05rem);
            color: var(--accent);
            font-weight: 600;
            margin-bottom: clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .title-meta {
            display: flex;
            gap: clamp(1rem, 3vw, 3rem);
            flex-wrap: wrap;
        }

        .meta-item {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .meta-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .meta-value {
            font-size: var(--body-size);
            color: var(--text-secondary);
            font-weight: 500;
        }

        /* ===========================================
           SLIDE HEADER (reusable)
           =========================================== */
        .slide-header {
            margin-bottom: clamp(0.6rem, 2vw, 2rem);
        }

        .slide-tag {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            text-transform: uppercase;
            letter-spacing: 0.15em;
            color: var(--accent);
            margin-bottom: clamp(0.2rem, 0.5vw, 0.5rem);
        }

        .slide-title {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            line-height: 1.2;
            color: var(--text-primary);
        }

        .slide-title em { color: var(--accent); font-style: italic; }

        /* ===========================================
           SLIDE 2 — METRIC METHODOLOGY
           =========================================== */
        #slide-2 {
            background:
                radial-gradient(ellipse at 85% 85%, rgba(74, 158, 255, 0.08) 0%, transparent 50%),
                var(--bg-primary);
        }

        .method-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: start;
            width: 100%;
        }

        .method-steps {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1.2rem);
        }

        .method-step {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1.2vw, 1.2rem);
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.5rem, 1.2vw, 1.2rem);
            transition: border-color 0.3s;
        }

        .method-step:hover { border-color: var(--accent2); }

        .step-num {
            flex-shrink: 0;
