<script>
/* === SLIDE PRESENTATION CONTROLLER === */
class SlidePresentation {
    constructor() {
        this.slides = Array.from(document.querySelectorAll('.slide'));
        this.currentIndex = 0;
        this.isScrolling = false;

        this.progressBar = document.getElementById('progressBar');
        this.navDotsContainer = document.getElementById('navDots');

        this.buildNavDots();
        this.setupIntersectionObserver();
        this.setupKeyboardNav();
        this.setupTouchNav();
        this.setupWheelNav();
        this.updateProgress(0);
    }

    /* Build navigation dots */
    buildNavDots() {
        this.slides.forEach((_, i) => {
            const dot = document.createElement('button');
            dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
            dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
            dot.addEventListener('click', () => this.goToSlide(i));
            this.navDotsContainer.appendChild(dot);
        });
        this.dots = Array.from(this.navDotsContainer.querySelectorAll('.nav-dot'));
    }

    /* Intersection Observer: triggers .visible class for animations */
    setupIntersectionObserver() {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    const idx = this.slides.indexOf(entry.target);
                    if (idx !== -1) {
                        this.currentIndex = idx;
                        this.updateProgress(idx);
                        this.updateDots(idx);
                    }
                }
            });
        }, { threshold: 0.5 });

        this.slides.forEach(slide => observer.observe(slide));
    }

    /* Keyboard navigation */
    setupKeyboardNav() {
        document.addEventListener('keydown', (e) => {
            if (['ArrowDown', 'ArrowRight', 'Space', 'PageDown'].includes(e.code)) {
                e.preventDefault();
                this.goToSlide(this.currentIndex + 1);
            } else if (['ArrowUp', 'ArrowLeft', 'PageUp'].includes(e.code)) {
                e.preventDefault();
                this.goToSlide(this.currentIndex - 1);
            } else if (e.code === 'Home') {
                e.preventDefault();
                this.goToSlide(0);
            } else if (e.code === 'End') {
                e.preventDefault();
                this.goToSlide(this.slides.length - 1);
            }
        });
    }

    /* Touch/swipe navigation */
    setupTouchNav() {
        let startY = 0;
        let startX = 0;

        document.addEventListener('touchstart', (e) => {
            startY = e.touches[0].clientY;
            startX = e.touches[0].clientX;
        }, { passive: true });

        document.addEventListener('touchend', (e) => {
            const dy = startY - e.changedTouches[0].clientY;
            const dx = startX - e.changedTouches[0].clientX;

            if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 40) {
                if (dy > 0) this.goToSlide(this.currentIndex + 1);
                else this.goToSlide(this.currentIndex - 1);
            }
        }, { passive: true });
    }

    /* Mouse wheel navigation with throttle */
    setupWheelNav() {
        let wheelTimeout = null;
        document.addEventListener('wheel', (e) => {
            if (wheelTimeout) return;
            wheelTimeout = setTimeout(() => { wheelTimeout = null; }, 800);
            if (e.deltaY > 30) this.goToSlide(this.currentIndex + 1);
            else if (e.deltaY < -30) this.goToSlide(this.currentIndex - 1);
        }, { passive: true });
    }

    /* Scroll to a specific slide index */
    goToSlide(index) {
        const clamped = Math.max(0, Math.min(this.slides.length - 1, index));
        this.slides[clamped].scrollIntoView({ behavior: 'smooth' });
    }

    /* Update progress bar width */
    updateProgress(index) {
        const pct = this.slides.length > 1
            ? (index / (this.slides.length - 1)) * 100
            : 100;
        this.progressBar.style.width = pct + '%';
    }

    /* Update which nav dot is active */
    updateDots(index) {
        this.dots.forEach((dot, i) => {
            dot.classList.toggle('active', i === index);
        });
    }
}

/* Initialize on DOM ready */
document.addEventListener('DOMContentLoaded', () => {
    new SlidePresentation();
});
</script>

